Arguments:
$ErrorActionPreference='Stop'
$llvm='C:\Program Files\LLVM\bin\llvm-objdump.exe'
$obj='benchmarks/SomeEngine.ECS.Relations.Benchmarks/obj/Release/net10.0/win-x64/native/SomeEngine.ECS.Relations.Benchmarks.obj'
function Read-SelectedSymbol([string]$readId) { $record=Get-Content -Raw -LiteralPath ('artifacts/benchmark-queue/'+$readId+'/result.json') | ConvertFrom-Json; $record.Arguments[2].Substring('--disassemble-symbols='.Length) }
$prior=Get-Content -LiteralPath 'artifacts/benchmark-queue/576d5f67efde4be59b269e16ec55356a/stdout.log'
$required=$prior | Where-Object { $_ -match '\bcallq\b.*WhereSelection.*RequiredRelationComponents' } | Select-Object -First 1
$null=$required -match '\bcallq\b.* <(.+)>$'
$targets=@($Matches[1],(Read-SelectedSymbol 'b37998b9269c467799ec8c289d9b36b6'),(Read-SelectedSymbol '23bbeb5c0bcf4a6793b09cc76d37bbff'),(Read-SelectedSymbol '1f802ac24d534c9e9f06463d07d73300'))
$symbolLines=@(& $llvm -t $obj)
if($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
foreach($line in $symbolLines) {
 if($line -match '\(sec\s+2\).* 0x[0-9a-f]+ (.+)$') {
  $symbol=$Matches[1]
  if($symbol -match 'FixedCandidatePairs__Enumerate<.*BitmapFilterOutput_6<.*(OneWayContacts|MutualContacts).*SpatialPairOutput.*WhereSelection') { $targets+=$symbol }
 }
}
$targets=@($targets | Sort-Object -Unique)
Write-Output ('SELECTED '+$targets.Count)
$targets | ForEach-Object {Write-Output ('TARGET '+$_)}
& $llvm -d -r ('--disassemble-symbols='+($targets -join ',')) $obj
exit $LASTEXITCODE

$names=@('finite-small-mask4-oneway','finite-small-mask4-mutual','default-small-dynamic90','default-large-dynamic90','character-middle-hair64-interleaved')
$files=@(rg --files --no-ignore artifacts/ecs-relations/measurements/optimized-13 | Where-Object {[IO.Path]::GetFileNameWithoutExtension($_) -in $names})
function P($a,[double]$q){$position=($a.Count-1)*$q;$lo=[int][Math]::Floor($position);$hi=[int][Math]::Ceiling($position);[double]$a[$lo]+([double]$a[$hi]-[double]$a[$lo])*($position-$lo)}
function Stats($values){$a=@($values|ForEach-Object{[double]$_}|Sort-Object);$sum=0.0;foreach($v in $a){$sum+=$v};$mean=$sum/$a.Count;$variance=0.0;foreach($v in $a){$variance+=($v-$mean)*($v-$mean)};[ordered]@{N=$a.Count;Median=(P $a .5);P95=(P $a .95);Iqr=((P $a .75)-(P $a .25));PopulationStd=[Math]::Sqrt($variance/$a.Count);Mean=$mean;Min=$a[0];Max=$a[-1]}}
function GroupStats($items){$items=@($items);[ordered]@{N=$items.Count;Ticks=(Stats $items.Ticks);TailCount=@($items|Where-Object Tail).Count;GCEvents=($items.GCEvents|Measure-Object -Sum).Sum;GCRows=@($items|Where-Object {$_.GCEvents -gt 0}).Count;AllocMin=($items.Alloc|Measure-Object -Minimum).Minimum;AllocMax=($items.Alloc|Measure-Object -Maximum).Maximum;WriteMedian=(P @($items.Write|Sort-Object) .5);WriteMax=($items.Write|Measure-Object -Maximum).Maximum;ConsumeMedian=(P @($items.Consume|Sort-Object) .5);ConsumeMax=($items.Consume|Measure-Object -Maximum).Maximum;PairsMin=($items.Pairs|Measure-Object -Minimum).Minimum;PairsMax=($items.Pairs|Measure-Object -Maximum).Maximum}}
foreach($file in $files){
$r=Get-Content -Raw -LiteralPath $file|ConvertFrom-Json
$cmp=$r.Comparisons|Where-Object Boundary -eq 'Query'|Select-Object -First 1
$raw=@($r.RawSamples|Where-Object Boundary -eq $cmp.Boundary)
$firstByRound=@{}
foreach($s in $raw){$key=[string]$s.Round;if(!$firstByRound.ContainsKey($key)){$firstByRound[$key]=$s.Side}}
$records=[Collections.Generic.List[object]]::new()
$index=0
foreach($s in $raw){
$gc=[ordered]@{};$gcEvents=0.0
foreach($p in $s.PSObject.Properties){if($p.Name -match '^Gen[012]'){$gc[$p.Name]=$p.Value;$gcEvents+=[double]$p.Value}}
$limit=if($s.Side -eq 'relation'){$cmp.Relation.P95Ticks}else{$cmp.Handwritten.P95Ticks}
[void]$records.Add([pscustomobject][ordered]@{Index=$index;Round=$s.Round;SideOrder=$s.SideOrder;ExecutionOrder=$(if($firstByRound[[string]$s.Round] -eq $s.Side){'first'}else{'second'});Side=$s.Side;Frame=$s.Frame;Boundary=$s.Boundary;Ticks=$s.ElapsedTicks;Query=$s.QueryTicks;FrameTicks=$s.FrameTicks;Write=$s.DataWriteTicks;Consume=$s.ConsumeTicks;Alloc=$s.FrameAllocatedBytes;ThreadAlloc=$s.FrameCurrentThreadAllocatedBytes;GCFields=$gc;GCEvents=$gcEvents;Pairs=$s.OutputPairCount;Tail=([double]$s.ElapsedTicks -ge [double]$limit)})
$index++
}
$frameGroups=@($records|Group-Object Side,Frame|ForEach-Object{[ordered]@{Side=$_.Group[0].Side;Frame=$_.Group[0].Frame;Data=(GroupStats $_.Group)}})
$orderGroups=@($records|Group-Object Side,SideOrder,ExecutionOrder|ForEach-Object{[ordered]@{Side=$_.Group[0].Side;SideOrder=$_.Group[0].SideOrder;ExecutionOrder=$_.Group[0].ExecutionOrder;Data=(GroupStats $_.Group)}})
$roundGroups=@($records|Group-Object Side,Round|ForEach-Object{[ordered]@{Side=$_.Group[0].Side;Round=$_.Group[0].Round;SideOrder=$_.Group[0].SideOrder;ExecutionOrder=$_.Group[0].ExecutionOrder;Data=(GroupStats $_.Group)}})
$tailGroups=@($records|Group-Object Side,Tail|ForEach-Object{[ordered]@{Side=$_.Group[0].Side;Tail=$_.Group[0].Tail;Data=(GroupStats $_.Group)}})
$allocGroups=@($records|Group-Object Side,Alloc,GCEvents|ForEach-Object{[ordered]@{Side=$_.Group[0].Side;Alloc=$_.Group[0].Alloc;GCEvents=$_.Group[0].GCEvents;Data=(GroupStats $_.Group)}})
$firstFrameGroups=@($records|Group-Object Side,{ $_.Frame -eq 0 }|ForEach-Object{[ordered]@{Side=$_.Group[0].Side;FirstFrame=($_.Group[0].Frame -eq 0);Data=(GroupStats $_.Group)}})
$top=@($records|Group-Object Side|ForEach-Object{@($_.Group|Sort-Object Ticks -Descending|Select-Object -First 18)})
$pairs=@($records|Group-Object Round,Frame|ForEach-Object{$a=$_.Group|Where-Object Side -eq 'relation';$b=$_.Group|Where-Object Side -eq 'handwritten';[pscustomobject][ordered]@{Round=$a.Round;Frame=$a.Frame;RelationOrder=$a.ExecutionOrder;R=$a.Ticks;H=$b.Ticks;Delta=([double]$a.Ticks-[double]$b.Ticks);Ratio=([double]$a.Ticks/[double]$b.Ticks);RTail=$a.Tail;HTail=$b.Tail;RGC=$a.GCEvents;HGC=$b.GCEvents;RAlloc=$a.Alloc;HAlloc=$b.Alloc}})
$pairedSummary=[ordered]@{Count=$pairs.Count;Delta=(Stats $pairs.Delta);Ratio=(Stats $pairs.Ratio);BothTail=@($pairs|Where-Object {$_.RTail -and $_.HTail}).Count;RelationTailOnly=@($pairs|Where-Object {$_.RTail -and !$_.HTail}).Count;HandTailOnly=@($pairs|Where-Object {!$_.RTail -and $_.HTail}).Count;TopPositive=@($pairs|Sort-Object Delta -Descending|Select-Object -First 12);TopNegative=@($pairs|Sort-Object Delta|Select-Object -First 8)}
$result=[ordered]@{Case=$file;Input=$r.Input;Device=$r.Device;Started=$r.StartedAtUtc;Finished=$r.FinishedAtUtc;OriginalComparison=$cmp;RawCounts=@($r.RawSamples|Group-Object Side,Boundary|Select-Object Name,Count);FirstRaw=$raw[0];Reproduced=@($records|Group-Object Side|ForEach-Object{[ordered]@{Side=$_.Name;Data=(Stats $_.Group.Ticks)}});ByFrame=$frameGroups;ByOrder=$orderGroups;ByRound=$roundGroups;ByTail=$tailGroups;ByAllocationAndGC=$allocGroups;ByFirstFrame=$firstFrameGroups;TopSamples=$top;Paired=$pairedSummary}
Write-Output ('ANALYSIS '+($result|ConvertTo-Json -Compress -Depth 12))
}
